import logging

import torch
import triton
import triton.language as tl

from flag_gems.ops.copysign import copysign_func as _copysign_generic_func
from flag_gems.ops.copysign import copysign_func_scalar as _copysign_generic_func_scalar
from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry

from ..utils.pointwise_dynamic import pointwise_dynamic

logger = logging.getLogger(__name__)

_FLAT_GRID_CAP = 48
_FLAT_DTYPES = (torch.float16, torch.bfloat16, torch.float32)
_FLAT_MAX_NUMEL = 2**31 - 1 - 65536
_INT32_LIMIT = 2**31

_ONCT_BLOCK = 32768
_ONCT_GRID_LIMIT = 65535
_ONCT_MIN_NUMEL = 524288


def _unwrap_if_constexpr(o):
    return o.value if isinstance(o, tl.constexpr) else o


@tl.constexpr
def _get_uint_dtype(num_bits):
    num_bits = _unwrap_if_constexpr(num_bits)
    return tl.core.get_int_dtype(num_bits, False)


@tl.constexpr
def _get_sign_bit_mask(num_bits):
    num_bits = _unwrap_if_constexpr(num_bits)
    return 1 << (num_bits - 1)


@libentry()
@triton.jit(do_not_specialize=["N"])
def _copysign_flat_kernel(X, Y, OUT, N, BLOCK: tl.constexpr, EVEN: tl.constexpr):
    pid = tl.program_id(0)
    num_ctas = tl.num_programs(0)
    num_tiles = tl.cdiv(N, BLOCK)
    for tile in tl.range(pid, num_tiles, num_ctas):
        offs = tile * BLOCK + tl.arange(0, BLOCK)
        if EVEN:
            x = tl.load(X + offs)
            y = tl.load(Y + offs)
        else:
            mask = offs < N
            x = tl.load(X + offs, mask=mask)
            y = tl.load(Y + offs, mask=mask)
        abs_val = tl.abs(x)
        num_bits: tl.constexpr = x.dtype.primitive_bitwidth
        uint_dtype = _get_uint_dtype(num_bits)
        sign_bit_mask: tl.constexpr = _get_sign_bit_mask(num_bits)
        other_u = y.to(uint_dtype, bitcast=True)
        res = tl.where((other_u & sign_bit_mask) != 0, abs_val * -1.0, abs_val)
        if EVEN:
            tl.store(OUT + offs, res)
        else:
            tl.store(OUT + offs, res, mask=mask)


@libentry()
@triton.jit(do_not_specialize=["N"])
def _copysign_onetile_kernel(X, Y, OUT, N, BLOCK: tl.constexpr, EVEN: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        x = tl.load(X + offs)
        y = tl.load(Y + offs)
    else:
        mask = offs < N
        x = tl.load(X + offs, mask=mask)
        y = tl.load(Y + offs, mask=mask)
    abs_val = tl.abs(x)
    num_bits: tl.constexpr = x.dtype.primitive_bitwidth
    uint_dtype = _get_uint_dtype(num_bits)
    sign_bit_mask: tl.constexpr = _get_sign_bit_mask(num_bits)
    other_u = y.to(uint_dtype, bitcast=True)
    res = tl.where((other_u & sign_bit_mask) != 0, abs_val * -1.0, abs_val)
    if EVEN:
        tl.store(OUT + offs, res)
    else:
        tl.store(OUT + offs, res, mask=mask)


def _copysign_flat_block(numel):
    if numel <= 8192:
        return max(triton.next_power_of_2(numel), 256)
    if numel <= 65536:
        return 8192
    if numel <= 524288:
        return 32768
    return 65536


def _use_onetile(x, numel):
    return (
        x.element_size() == 4
        and _ONCT_MIN_NUMEL < numel
        and numel % _ONCT_BLOCK == 0
        and triton.cdiv(numel, _ONCT_BLOCK) <= _ONCT_GRID_LIMIT
    )


def _max_flat_offset(t):
    offset = 0
    for size, stride in zip(t.shape, t.stride()):
        if size > 1:
            offset += (size - 1) * stride
    return offset


def _launch_flat(x, y, out, numel):
    if _use_onetile(x, numel):
        block = _ONCT_BLOCK
        grid = (triton.cdiv(numel, block),)
        even = True
        kernel = _copysign_onetile_kernel
    else:
        block = _copysign_flat_block(numel)
        grid = (min(triton.cdiv(numel, block), _FLAT_GRID_CAP),)
        even = numel % block == 0
        kernel = _copysign_flat_kernel
    for attempt in range(3):
        try:
            with torch_device_fn.device(x.device):
                kernel[grid](
                    x,
                    y,
                    out,
                    numel,
                    BLOCK=block,
                    EVEN=even,
                    num_warps=2,
                )
            return
        except Exception as exc:
            if attempt == 2:
                raise
            logger.warning(
                "copysign flat kernel launch failed (attempt %d): %s",
                attempt + 1,
                exc,
            )


@pointwise_dynamic(promotion_methods=[(0, 1, "DEFAULT")])
@triton.jit
def copysign_func(input, other):
    abs_val = tl.abs(input)
    num_bits: tl.constexpr = input.dtype.primitive_bitwidth
    uint_dtype = _get_uint_dtype(num_bits)
    sign_bit_mask: tl.constexpr = _get_sign_bit_mask(num_bits)
    other_u = other.to(uint_dtype, bitcast=True)
    return tl.where((other_u & sign_bit_mask) != 0, abs_val * -1.0, abs_val)


@pointwise_dynamic(is_tensor=[True, False], promotion_methods=[(0, 1, "DEFAULT")])
@triton.jit
def copysign_func_scalar(input, other):
    # Scalar `other` specializes the sign branch at trace time. The scalar is
    # narrowed to the (promoted) input dtype before the bitcast: fp32 -> 16-bit
    # bitcast is rejected by Triton, and sign is preserved under any rounding
    # (subnormal/overflow-to-inf included), matching aten scalar semantics.
    abs_val = tl.abs(input)
    num_bits: tl.constexpr = input.dtype.primitive_bitwidth
    uint_dtype = _get_uint_dtype(num_bits)
    sign_bit_mask: tl.constexpr = _get_sign_bit_mask(num_bits)
    other_u = other.to(input.dtype).to(uint_dtype, bitcast=True)
    return tl.where((other_u & sign_bit_mask) != 0, abs_val * -1.0, abs_val)


def _fast_out_ready(out, input):
    return out is None or (
        out.dtype == input.dtype and out.shape == input.shape and out.is_contiguous()
    )


def copysign(input, other, *, out=None):
    logger.debug("GEMS_ENFLAME COPYSIGN")
    if isinstance(other, torch.Tensor):
        numel = input.numel()
        if (
            0 < numel <= _FLAT_MAX_NUMEL
            and input.dtype in _FLAT_DTYPES
            and other.dtype == input.dtype
            and other.shape == input.shape
            and input.is_contiguous()
            and other.is_contiguous()
            and _fast_out_ready(out, input)
        ):
            result = torch.empty_like(input) if out is None else out
            _launch_flat(input, other, result, numel)
            return result
        if (
            numel <= _FLAT_MAX_NUMEL
            and _max_flat_offset(input) < _INT32_LIMIT
            and _max_flat_offset(other) < _INT32_LIMIT
            and _fast_out_ready(out, input)
        ):
            if out is None:
                return copysign_func(input, other)
            copysign_func(input, other, out0=out)
            return out
        if out is None:
            return _copysign_generic_func(input, other)
        _copysign_generic_func(input, other, out0=out)
        return out
    numel = input.numel()
    if (
        numel <= _FLAT_MAX_NUMEL
        and _max_flat_offset(input) < _INT32_LIMIT
        and _fast_out_ready(out, input)
    ):
        if out is None:
            return copysign_func_scalar(input, other)
        copysign_func_scalar(input, other, out0=out)
        return out
    if out is None:
        return _copysign_generic_func_scalar(input, other)
    _copysign_generic_func_scalar(input, other, out0=out)
    return out


def copysign_out(input, other, *, out=None):
    logger.debug("GEMS_ENFLAME COPYSIGN_OUT")
    return copysign(input, other, out=out)
